import random

print('🎮 Number Guessing Game')
secret = random.randint(1, 100)
attempts = 0

while True:
    try:
        guess = int(input('Guess (1-100): '))
        attempts += 1
        if guess < secret:
            print('📉 Too low!')
        elif guess > secret:
            print('📈 Too high!')
        else:
            print(f'🎉 Correct! You got it in {attempts} attempts!')
            break
    except ValueError:
        print('Please enter a valid number.')
